  readonly position: SystemVectorTuple;
  readonly velocity: SystemVectorTuple;
  readonly quaternion: SystemQuaternionTuple;
}

export type SystemFlightTarget =
  | {
      readonly kind: 'system_body';
      readonly address: PlanetAddress;
      readonly worldId: string;
    }
  | {
      /**
       * A station in this system.
       *
       * Deliberately its own kind rather than a fourth planet slot. An spaceStation
       * has no terrain, no surface residency and no planet identity; borrowing the
       * planet grammar would make every consumer of `system_body` — terrain
       * preparation, surface handoff, the atmosphere envelope — start receiving a
       * body it cannot generate. Every existing reader tests `kind ===
       * 'system_body'` positively, so they all correctly ignore this one.
       */
      readonly kind: 'space_station';
      readonly address: SpaceStationAddress;
      readonly worldId: string;
    }
  | {
      readonly kind: 'star_system';
      readonly coordinate: SystemCoordinate;
      readonly systemId: string;
    };

export interface SystemFlightSnapshot {
  readonly systemId: string;
  readonly layoutVersion: number;
  readonly locationMode: SystemLocationMode;
  readonly activePlanetId: string | null;
  readonly lastActivePlanetId: string | null;
  readonly pose: SystemShipPose;
  readonly target: SystemFlightTarget | null;
  readonly renderOrigin: SystemVectorTuple;
  readonly activationEpoch: number;
}

export interface SystemPoseWriterLease {
  readonly owner: string;
  readonly leaseId: number;
}

export interface InterstellarSystemReset {
  system: SystemCoordinate;
  layoutVersion?: number;
  locationMode?: SystemLocationMode;
  activePlanetId?: string | null;
  pose: SystemShipPose;
  renderOrigin?: SystemVectorTuple;
}

export interface SystemPlanetHandoffCommit {
  worldId: string;
  renderOrigin: SystemVectorTuple;
  expectedActivationEpoch: number;
}

/** Immutable receipt emitted only after a same-system planet handoff commits. */
export interface SystemPlanetHandoffReceipt {
  readonly systemId: string;
  readonly worldId: string;
  readonly previousActivationEpoch: number;
  readonly activationEpoch: number;
}

type Listener = () => void;
type SystemPlanetHandoffListener = (receipt: SystemPlanetHandoffReceipt) => void;

const ZERO_VECTOR: SystemVectorTuple = Object.freeze([0, 0, 0]);
const IDENTITY_QUATERNION: SystemQuaternionTuple = Object.freeze([0, 0, 0, 1]);

