export function systemPlanetCount(coordinate: SystemCoordinate): 1 | 2 | 3 {
  const system = normalizeCoordinate(coordinate);
  const systemSeed = nonZeroHash(`${SYSTEM_LAYOUT_SEED_NAMESPACE}:${system.x}:${system.y}`);
